; ram_variables_by_use.s -- main-CPU RAM variables named from the code that uses them (audit WP17).
; The names and reasons are v10's, through v6's copy (v6/maincpu/shared/ram_variables_by_use.s); the
; values here are v5's own, derived by scripts/tools/name_kn5000_ram.py --ref v6 from the same
; instructions in the same routines of v6 (scripts/converters/port_ram_names.py; a corrected line
; says so).  Names it could not derive for v5 are left out.
	.equ BOOT_STAGE,			0x0400	; boot progress: Boot_PostSelfTest stores 2 before Kernel_InitRam and 3 after it, Boot_DisplayScreen 6 after the first screen group and 0x80 after the last; NMI_ClearGuardAndHalt stores 0.  Only NMI_StorePayloadChecksums reads it: it stores the power-fail checksums only at 0x80 (boot complete, power-fail save armed)
	.equ BOOT_CONFIG_FLAGS,			0x0406	; bit 7 = boot finished normally (Boot_SetConfigFlag7 sets it in Boot_DisplayScreen, Boot_ClearConfigFlag7 clears it at the start of Boot_InitPeripherals)
	.equ ACC_CLOCK,				0x0415	; accompaniment clock within the beat, 0..95 (INTTR4_CheckSeqEnable counts it, ClkTick_Src2FineBeatCheck by 4 per MIDI clock)
	.equ ACC_BEAT,				0x0416	; beat within the measure; INTTR4_SeqAutoStart compares it with ACC_BEATS_PER_BAR - 1, the BeatLed_*Masks show it on the START/STOP BEAT LEDs
	.equ PLAY_CLOCK,			0x0417	; tick within the beat, 0..95, counted by INTTR4_HANDLER while PLAY_TRANSPORT_STATE runs (INTTR4_MetroBeat_Check stops on 0 / 24 / 48 / 72)
	.equ PLAY_BEAT_COUNT,			0x0418	; word: beats counted since the play transport started
	.equ ACC_TRANSPORT_STATE,		0x041e	; transport of the accompaniment clock ACC_CLOCK / ACC_BEAT (bit 2 = running gates them in INTTR4_CheckSeqEnable; AccAutoPlay_* test it), coded like SEQ_TRANSPORT_STATE (1, 6, 8, 12, 16; AccPlayMode_StartAccPlay stores 1); 128 / 134 = waiting for synchro start: INTTR4_SeqAutoStart starts PLAY_TRANSPORT_STATE and SEQ_TRANSPORT_STATE at the end of a bar
	.equ PLAY_TRANSPORT_STATE,		0x0420	; the play transport, coded like SEQ_TRANSPORT_STATE: 1 start pending, 6 running (bit 2 gates PLAY_CLOCK / PLAY_BEAT_COUNT in INTTR4_HANDLER; Audio_WaitForReady and the demo song player wait on it), bit 3 = stop at the next 24-tick boundary (INTTR4_MetroBeat_Check), 16 stopped; AccPlayMode_* start and stop it (ssf-presentation.md calls it the sequencer transport lane)
	.equ ACC_BEATS_PER_BAR,			0x0433	; beats per measure of the style; 3 or 6 select the three-beat LED pattern (BeatLed_ThreeBeatMasks)
	.equ ACC_BAR_COUNT,			0x0434	; bars the accompaniment clock has completed (INTTR4_SeqTick_CheckBeat counts them; synchro start waits for 1)
	.equ ACC_SECTION_BAR,			0x0435	; bar within the style section, back to 0 after STYLE_SECTION_LAST_MEASURE (INTTR4_SeqTick_CheckBeat)
	.equ INTERCPU_XFER_PTR,			0x05da	; the source address of the inter-CPU transfer in progress (InterCPU_Send_WaitAck, E1Bulk_WaitAck; inter-cpu-protocol.md)
	.equ INTERCPU_XFER_COUNT,		0x05de	; word: its byte count
	.equ INTERCPU_XFER_STATE,		0x05e0	; 0 = idle, 1 while a packet or E2 header is sent, 2 for an E1 bulk transfer's first phase (INTTC2_HANDLER clears it)
	.equ INTERCPU_RX_STATE,			0x05e2	; receive state of the inter-CPU link: 0 idle, 1 data command, 2 latch read, 3 E2 command, 4 E1 DMA transfer (INT0_* set it, INTTC0_HANDLER clears it)
	.equ INTERCPU_RX_HEADER,		0x05e4	; the header byte INT0_ReadLatch took from the latch
	.equ SEMENU_PART_MASK,			0x065e	; the sound editor's enabled parts, one bit per part (SeMenu_SetPartEnabled)
	.equ SEMENU_PART_MODE,			0x06ae	; the sound editor's part layout: 1 = 2 parts, else 4 (SeMenu_DrawPartSelector, SeMenu_DrawPartRadioButtons)
	.equ SEMENU_GFX_X,			0x06c6	; word: x origin of the sound editor's graphic (mini keyboard, envelope curve: SeMenu_DrawKeyboardGraphic)
	.equ SEMENU_GFX_Y,			0x06c8	; word: its y origin
	.equ FLASH_SLOT_ASSIGN_LIST,		0x07a0	; the slot assignment list Flash_AssignSlotsToBlocks builds: {block, 0x500 | slot} records, bit 7 set for small slots (Flash_CopyBlocksToSlots, Flash_WriteSlotOwnerMap consume it)
	.equ STYLE_WORK_IMAGE_PTR,		0x0c72	; the style work image (0x69800, set by Flash_InitExtMemAddrs); the legacy-image converters build there
	.equ FLASH_SECTOR_IMAGE_PTR,		0x0c96	; RAM image of the custom-data flash's section-7 sector (0x69800, Flash_InitExtMemAddrs); Flash_CopyBlocksToSlots / Flash_WriteBackSlot* build it before the sector is rewritten
	.equ TRACK_ASSIGN_CURSOR,		0x0cdf	; the track (0..15) the TRACK ASSIGN page's cursor is on; 8 = the second page (SqTrAs_Cursor*)
	.equ DEMO_DEBOUNCE,			0x0d33	; debounce counter of the demo selection buttons (Demo_SelectEntry_Debounce)
	.equ PLAYBACK_START_ARMED,		0x0d34	; 1 once the start countdown is armed (PlayMode_ArmStartCountdown), 0 when disarmed
	.equ SQSTEP_CLOCK,			0x0d57	; clock within the beat at the song-data cursor, 0..95 (SqStep_AdvanceClockByStep, SqStep_SeekForwardByDistance store it)
	.equ SQSTEP_WRAP_COUNT,			0x0d58	; word: clock-wrap markers (0x81) passed since the start of the cursor track (SqStep_WriteClockWrapMarker increments it)
	.equ SQSTEP_UNITS,			0x0d5a	; word: whole 96-clock units from the start of the cursor track to the cursor; the seeks count it
	.equ SQSTEP_BEAT,			0x0d5c	; beat within the measure at the cursor, from 0
	.equ SQSTEP_MEASURE_BEATS,		0x0d5d	; beats in the cursor's measure: UIDisp_StepMeasureForward seeks (this) - SQSTEP_BEAT beats to the next measure
	.equ SEQ_SELECTED_TRACK,		0x0d60	; the selected track, 1..16; the status bar redraws when it changes (Display_UpdateRegion0_Check)
	.equ SQSTEP_DISPLAY_MODE,		0x0d65	; display mode of the cursor track, from its TRACK ASSIGN value: 1 = note track, 3 = RHYTHM track; (this) & 3 indexes DisplayMode_Dispatch_Tbl / SoundEvt_ModeDispatch_Tbl
	.equ SQSTEP_SEEK_UNITS,			0x0dcd	; distance in 96-clock units SqStep_SeekForwardByDistance moves the cursor; callers preset it
	.equ SQSTEP_SEEK_CLOCK,			0x0dce	; the clock (0..95) SqStep_SeekForwardByDistance stops on
	.equ SQSTEP_RECORD_LENGTH,		0x0dd2	; length of the event record being step-recorded: 3 modulation, 4 pitch bend or tempo
	.equ SQSTEP_HELD_COUNT,			0x0dd4	; keys held while step-recording, up to 8 (TempoRingBuf_ReadNoteIntoHeldList)
	.equ STATUS_POPUP_ID,			0x0def	; the pop-up the status bar's region 0 shows: 1 accompaniment parameter, 2 incoming control line, 4 program change, 10 part parameter, 12 RHYTHM track (ParamPopup_*, Display_ModePopupDispatch, SqStep_SetPopupIdForDisplayMode)
	.equ PERF_STEP_AMOUNT,			0x0df2	; +1 or 0xff (-1): what PerfMode_StepCursorEventByte adds
	.equ PERF_STEP_FIELD,			0x0df3	; which byte of the event at the cursor it steps (2, 3 velocity, 4)
	.equ SQSTEP_ROW1_MEASURE,		0x0e4c	; word: measure number of the step grid's row above the cursor row (SqStep_SetupPrevGridRow; capped at 1000)
	.equ SQSTEP_ROW2_MEASURE,		0x0e4e	; word: measure number of the cursor row
	.equ SQSTEP_ROW3_MEASURE,		0x0e50	; word: measure number of the row below (SqStep_SetupNextGridRow); 0 = no row
	.equ SQSTEP_ROW1_BEATS,			0x0e52	; beats shown in row 1 (its segment count; Scoop_TitleBar_GetPartConfig draws one block per beat)
	.equ SQSTEP_ROW2_BEATS,			0x0e53	; beats shown in row 2
	.equ SQSTEP_ROW3_BEATS,			0x0e54	; beats shown in row 3
	.equ SEQ_CURSOR_TRACK,			0x0eee	; the cursor track, 1..16, of the step-record and scoop screens (SqStep_SetDisplayModeFromTrack copies SEQ_SELECTED_TRACK into it)
	.equ SEQ_EVT_STATUS,			0x0fab	; status byte of the MIDI event the song player is executing (MidiEvent_*, MidiNoteOn_*); only the low nibble, the channel, is used
	.equ SEQ_EVT_DATA1,			0x0fac	; its first data byte (clamped to 0x7f with SEQ_EVT_DATA2 by MidiEvent_ClampVelocityA_High)
	.equ SEQ_EVT_DATA2,			0x0fad	; its second data byte
	.equ SEQ_EVENT_ABORT,			0x10e3	; 0 = carry on; 255 = the block chain ran out (ToneGen_AdvancePosition with no free block) or SeqTrack_ValidateAndAssignVoices found no dispatch slot.  The event handlers skip their register write when it is set and clear it after each event
	.equ POPUP_PART,			0x10f1	; part shown by the parameter pop-up, an index into StringData_PartNames (ParamPopup_Part*)
	.equ POPUP_VALUE,			0x10f3	; value the parameter pop-up shows (decimal, a signed amount or an on/off bit, by pop-up)
	.equ SEQ_BLOCK_PTR,			0x10fd	; the 256-byte block being read or written: SMF_CalcPageAddress and its twins store SEQ_BLOCK_POOL + (n - 1) * 0x100 here; nested walks save and restore it
	.equ SEQ_BLOCK_POOL_COPY,		0x110a	; a copy of SEQ_BLOCK_POOL (DispatchHandler_* store it through `ld xhl, ...`), the base SeqNode_ResolveSlotPtr and SetWall_ResolveStreamPtr add to
	.equ SMF_FILE_PTR,			0x1118	; the byte pointer into the SMF file data being read or written: FloppyIO_ReadNextByte reads through it, SMF_WriteByte writes through it
	.equ PART_PARAM_SELECT,			0x111c	; the part parameter shown: 0 PAN, 1 KEY SHIFT, 2 TUNING, 3 BEND SENS (PartParam_LoadSelectedValue)
	.equ PART_PARAM_VALUE,			0x111d	; its value, shown under that label by DisplayStr_ShowPartParamLine
	.equ PLAYBACK_COUNTDOWN,		0x1144	; ticks before an armed playback starts: 10 when armed (PlayMode_LoadStartCountdown), CDlikeSwitch_PlaybackTimer counts it down
	.equ SEQ_BLOCK_POOL,			0x1d56	; base of the sequencer's pool of 256-byte data blocks: SeqInit_SetBaseAddress sets 0xb0000; block n (1-based) is at this + (n - 1) * 0x100	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x1d5a
	.equ SEQ_CHORD_TYPE,			0x22fa	; chord type of the song's chord part, recognized from its notes by NoteDisplay_StoreAndDispatch (BitMapOut_PrepareAndDisplaySimple, BitMapOut_WriteMultiIdx); AccChord_ReadAndStoreKeys takes it for ACC_CHORD_TYPE while SEQ_CHORD_FROM_SONG is set; the four fields are a byte each, two apart	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2300
	.equ SEQ_CHORD_ROOT,			0x22fc	; root (1 = C .. 12 = B) of SEQ_CHORD_TYPE	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2302
	.equ SEQ_CHORD_BASS,			0x22fe	; bass root of SEQ_CHORD_TYPE	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2304
	.equ SEQ_CHORD_FLAGS,			0x2300	; CHORD_FLAGS as the recognizer left them for the song's chord (same writers as SEQ_CHORD_TYPE); AccChord_ReadAndStoreKeys copies it to ACC_CHORD_FLAGS.  Every writer copies a CHORD_FLAGS value, and no code sets CHORD_FLAGS bit 0 (notes/kn5000-notes-2026-11-06)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2306
	.equ SEQ_CHORD_FROM_SONG,		0x2302	; 1 while song slot 0 has an active part of type 0x0d whose voice-table flag is set (Accomp_ValidateAutoPlayChordVoice): the accompaniment follows SEQ_CHORD_* instead of the keyboard's chord; SeqAcc_ClearStepCounter, SeqPlay_InitDemo_PartLoopNext and Seq_HandleModeTransition clear it	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2308
	.equ SEQ_OP_MEASURES,			0x25c4	; word: measures the edit operation covers, last - first + 1 (the EXECUTE handlers MainExeCall_OnTitleSq* store it; SeqPart_* and the Seq_Validate* checks read it)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x25de
	.equ SEQ_PART_LOOP,			0x25c6	; the part (0..15) the sequencer's per-part loops are on (SeqAcc_ProcessTempo_*, Portamento_Scan*, SeqScan_*)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x25e0
	.equ SQEDT_TRKCLR_MASK,			0x25ce	; word: TT_SQTRKCLR's track mask; EXECUTE clears every track whose bit is set and zeroes it	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x25e8
	.equ SQEDT_VELOCNG_LAST,		0x25e0	; TT_SQVELOCNG: last measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x25fa
	.equ SQEDT_QTZ_LAST,			0x25e2	; TT_SQQTZ: last measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x25fc
	.equ SEQ_OP_QUANTIZE,			0x25e4	; the quantize value, SQEDT_QTZ_VALUE doubled (SeqPart_VelocityCurveCalc reads it)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x25fe
	.equ SQEDT_QTZ_STRENGTH,		0x25e6	; TT_SQQTZ: quantize strength, 0..100 (SeqParams_InitDefaults stores 100; AppEvent_ChainDispatch1_IncQtzStrength / AppEvent_InlineHandler_DecQtzStrength step it within 0..100 and redraw item 8; SeqPart_VelocityCurveCalc's caller returns early at 100)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2600
	.equ SQEDT_QTZ_WINDOW,			0x25e8	; TT_SQQTZ: quantize window, signed -100..+100 (SeqParams_InitDefaults stores 100; AppEvent_ChainDispatch1_IncQtzWindow / AppEvent_InlineHandler_DecQtzWindow step it between 0x9c = -100 and 100 and redraw item 9)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2602
	.equ SQEDT_ADVDLY_TRACK,		0x25ea	; TT_SQADVDLY: track	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2604
	.equ SQEDT_ADVDLY_FROM,			0x25ec	; TT_SQADVDLY: first measure (word; also the default the FM string shows)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2606
	.equ SQEDT_ADVDLY_LAST,			0x25ee	; TT_SQADVDLY: last measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2608
	.equ SQEDT_NOTECNG_TRACK,		0x25f4	; TT_SQNOTECNG (note change): track	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x260e
	.equ SQEDT_NOTECNG_FROM,		0x25f6	; TT_SQNOTECNG: first measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2610
	.equ SQEDT_NOTECNG_LAST,		0x25f8	; TT_SQNOTECNG: last measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2612
	.equ SQEDT_TRNS_TRACK,			0x2602	; TT_SQTRNS (transpose): track	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x261c
	.equ SQEDT_TRNS_FROM,			0x2604	; TT_SQTRNS: first measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x261e
	.equ SQEDT_TRNS_LAST,			0x2606	; TT_SQTRNS: last measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2620
	.equ SQEDT_MERS_LAST,			0x260c	; TT_SQMERS: last measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2626
	.equ SQEDT_MCP_LAST,			0x260e	; TT_SQMCP: last source measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2628
	.equ SQEDT_MCP_REPEAT,			0x2610	; TT_SQMCP: repeat count	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x262a
	.equ SQEDT_MDEL_LAST,			0x2612	; TT_SQMDEL: last measure (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x262c
	.equ SQEDT_MINS_LAST,			0x2614	; TT_SQMINS: last measure of A (word)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x262e
	.equ SQEDT_MINS_REPEAT,			0x2616	; TT_SQMINS: repeat count	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2630
	.equ SEQ_OP_FROM,			0x2618	; word: first measure of the edit operation (MainExeCall_OnTitleSq*)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2632
	.equ SEQ_QTZ_TICK,			0x261e	; the tick within the beat of the event being quantized: the byte SeqData_ReadNextByte returns (SeqPart_VelExprClamp), which SeqPart_VelocityCurveCalc splits into grid zones (QtzGrid48: at 24 / 72)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2638
	.equ SEQ_QTZ_ZONE_EDGE_A,		0x2626	; first of the edge pair of the grid zone SEQ_QTZ_TICK falls in (SeqPart_VelocityCurveCalc: 48 for quantize value 0, else from SeqPart_VelCurveData_Table / SeqPart_VelZoneLookup_Table by zone)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2640
	.equ SEQ_QTZ_ZONE_EDGE_B,		0x2628	; second of that edge pair (SeqPart_VelZoneLookup_Table_2 by zone; 48 for quantize value 0)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2642
	.equ SEQ_OP_ERASE_CHOICE,		0x2636	; what a measure erase removes (SQEDT_MERS_CHOICE; SeqPart_FullLoad picks its mode by it)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2650
	.equ SEQ_OP_VELOCITY,			0x263a	; the velocity amount of a velocity change (SQEDT_VELOCNG_AMOUNT)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2654
	.equ SEQ_DATA_OFFSET,			0x264c	; word: byte offset of the song-data cursor in SEQ_DATA_BLOCK, 5..255 (5 = first byte after the block header); at 255 ToneGen_AdvancePosition moves on to a new linked block	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2666
	.equ SEQ_START_MEASURE,			0x264e	; word: the measure playback starts from, sign-magnitude (0x8002 = 2 measures before measure 1): punch-in minus SEQ_COUNT_IN (SeqPlay_UpdateStartFromPunchIn)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2668
	.equ SCOOP_DST_BLOCK_PTR,		0x2660	; address of the destination block of the scoop display's chained copy (SeqData_ChainNextDstBlock follows the +3 link and stores the next block here)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x267a
	.equ SCOOP_SRC_BLOCK_PTR,		0x2664	; address of its source block (SeqData_ChainPrevSrcBlock follows the +1 link)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x267e
	.equ SEQ_OP_DEST_TRACK,			0x2668	; destination track of a copy / insert operation (SQEDT_MCP_TRACK_B, SQEDT_MINS_TRACK_B)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2682
	.equ SEQ_OP_DEST_MEASURE,		0x266c	; word: destination measure of a copy / insert operation (SQEDT_MCP_AT, SQEDT_MINS_AT)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2686
	.equ NOTEEDIT_BASE_KEY,			0x277e	; the lowest key the note-edit display shows; MT_GetKb1Str / MT_GetKb2Str name it and the next (BmDrEdit_ChordScroll* step it)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2798
	.equ SEQ_BLOCK_TOTAL,			0x2851	; word: blocks in the pool, 1240 (SeqInit_SetBaseAddress); DispatchHandler_InitAllSlots starts SEQ_FREE_BLOCKS from it, the song-usage percentages divide by it	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x286d
	.equ TRACK_ASSIGN_EDIT_VALUE,		0x2857	; the TRACK ASSIGN value being edited, reloaded from SEQ_TRACK_ASSIGN when the cursor moves (SetWall_UpdateSlotIndex)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2873
	.equ SEQ_TRACK,				0x285b	; the track (1..16) a sequencer operation or loop works on; 127 = all tracks (the edit titles' track 0x11, MainExeCall_OnTitleSq*); MainExe_SongMem* and SeqStep_MultiTrackProcess loop it over 1..16	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2877
	.equ SEQ_SONG,				0x285c	; the song (0..9) the song-memory routines (SeqVoice_InitEntry ...) address; SeqVoice_InitEntryForCurrentBank and SeqStep_TrackChange set it to SEQ_CURRENT_SONG or another song for one call and restore it	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2878
	.equ SEQ_EDIT_FLAGS,			0x285f	; flags of the song-data edit and scan routines: bit 2 = take the measure lengths from the RHYTHM track (Seq_FindRhythmTrack sets it), bit 5 = a scan met the end marker (SeqTrack_ScanSetEndFlag, SetWall_ForwardSkip); bits 0, 3, 4, 6 and 7 are working flags of the SeqPart_* copy / exchange / load operations	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x287b
	.equ SEQ_WRITE_BLOCK_PTR,		0x2865	; the block SMF_Config* write output bytes into, at (this + IY); set from SEQ_BLOCK_PTR when a new block is started (IY = 5, past the block header)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2881
	.equ SEQOP_PRIMARY_OFFSET,		0x2869	; word: offset of the primary song-data cursor of the SeqPart_* / SMF_Config* walks (SeqPart_ReadByte_Primary, SeqPart_WriteByte_Primary); 5 = first byte of a block, 255 = its last	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2885
	.equ SEQOP_PRIMARY_BLOCK,		0x286b	; word: block of the primary cursor (SMF_AdvanceInPageChain follows the +3 link when the offset passes 255)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2887
	.equ SEQOP_SECONDARY_OFFSET,		0x286d	; word: offset of the secondary song-data cursor (SeqPart_WriteByte_Secondary, PartCtrl_AdvanceReadPos)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x2889
	.equ SEQOP_SECONDARY_BLOCK,		0x286f	; word: block of the secondary cursor (SMF_AdvanceReadPtr, SeqCopy_ComparePositionLoop)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x288b
	.equ SEQ_RTMCFG,			0x288b	; rtmcfg, the firmware's own name (GetAdr_rtmcfg returns its address): sequencer / accompaniment playback flags; bit 2 = ignore incoming MIDI Start / Continue (Transport_EnableMidiStartContinue clears it)	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x28a7
	.equ SEQ_REC_TRACKS,			0x288c	; word: one bit per track armed for recording (SqRealRecTitleFunc sets them through SeqVoice_SetOrClearBitMask); Audio_CheckInitStatus reports them as audio group B	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0x28a8
