	.equ HARMONY_REF_NOTE,			0xcdea	; harmony reference note: the lowest note of the list Harmony_FindReferenceNote scans, if in 25..102, else 0xff	; v7 address, derived from v10's uses (name_kn5000_ram.py); was a copy of v10's 0xceaa	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0xce0e
	.equ HARMONY_REF_BYTE,			0xcdeb	; the other byte of that note's list entry	; v7 address, derived from v10's uses (name_kn5000_ram.py); was a copy of v10's 0xceab	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0xce0f
