	.equ CHORD_RECOGNIZE_DELAY,		0xcdf3	; ticks left before a delayed chord recognition (5 when started)	; v7 address, derived from v10's uses (name_kn5000_ram.py); was a copy of v10's 0xceb3	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0xce17
