	.equ CHORD_TYPE,			0xce1f	; type of the recognized chord (Chord_ApplyCurrentChord)	; v7 address, derived from v10's uses (name_kn5000_ram.py); was a copy of v10's 0xcedf	; v6 address, derived from v7's uses (name_kn5000_ram.py); was a copy of v7's 0xce43
